const PHASE_CONFIG = {
	ADVANCING: { color: "#2ecc71", symbol: "▲" },
	STALEMATE: { color: "#f39c12", symbol: "◆" },
	RETREATING: { color: "#e74c3c", symbol: "▼" },
	COLLAPSING: { color: "#c0392b", symbol: "✗" },
};

function sidePairKey(uidA, uidB) {
	return uidA < uidB ? `${uidA}|${uidB}` : `${uidB}|${uidA}`;
}

function synchronizeSideUidCounter() {
	for (const uid of sideUids) {
		const match = /^side-(\d+)$/.exec(String(uid || ""));
		if (match) _nextSideUid = Math.max(_nextSideUid, Number(match[1]) + 1);
	}
}

function allocateSideUid() {
	let uid;
	do {
		uid = `side-${_nextSideUid++}`;
	} while (sideUids.includes(uid));
	return uid;
}

function ensureSideIdentities(reset = false) {
	if (reset) {
		sideUids = [];
		hostileSidePairs.clear();
	}
	synchronizeSideUidCounter();
	for (let i = 0; i < sides.length; i++) {
		if (!sideUids[i]) sideUids[i] = allocateSideUid();
	}
	if (sideUids.length > sides.length) sideUids.length = sides.length;
}

export function rebuildHostilityMatrix() {
	ensureSideIdentities();
	hostilityMatrix = createHostilityMatrix(
		sides.length,
		hostileSidePairs,
		sideUids,
		MAX_SIDES,
	);
	_frontlinePolys = {};
	invalidateFrontlineField();
	for (const u of units) {
		if (
			u._cachedTarget &&
			!areSidesHostile(u.sideIndex, u._cachedTarget.sideIndex)
		) {
			u._cachedTarget = null;
		}
	}
	reconcileOperationalAiLifecycle("hostility-matrix");
	return hostilityMatrix;
}

export function resetSideHostilities() {
	ensureSideIdentities(true);
	for (let a = 0; a < sides.length; a++) {
		if (!sides[a]?.length) continue;
		for (let b = a + 1; b < sides.length; b++) {
			if (!sides[b]?.length) continue;
			hostileSidePairs.add(sidePairKey(sideUids[a], sideUids[b]));
		}
	}
	rebuildHostilityMatrix();
}

export function areSidesHostile(sideA, sideB) {
	if (
		!Number.isInteger(sideA) ||
		!Number.isInteger(sideB) ||
		sideA < 0 ||
		sideB < 0 ||
		sideA >= MAX_SIDES ||
		sideB >= MAX_SIDES ||
		sideA === sideB
	)
		return false;
	return hostilityMatrix[sideA * MAX_SIDES + sideB] === 1;
}

export function setSidesHostile(sideA, sideB, hostile = true) {
	ensureSideIdentities();
	const uidA = sideUids[sideA];
	const uidB = sideUids[sideB];
	if (!uidA || !uidB || sideA === sideB) return false;
	const key = sidePairKey(uidA, uidB);
	if (hostile) hostileSidePairs.add(key);
	else hostileSidePairs.delete(key);
	rebuildHostilityMatrix();
	return true;
}

function getActiveHostilePairs() {
	const pairs = [];
	for (let a = 0; a < sides.length; a++) {
		if (!sides[a]?.length) continue;
		for (let b = a + 1; b < sides.length; b++) {
			if (sides[b]?.length && areSidesHostile(a, b)) pairs.push([a, b]);
		}
	}
	return pairs;
}

function getUnitDiscipline(unit) {
	if (!Number.isFinite(unit._discipline)) {
		const seed =
			Math.sin((unit.id || 0.5) * 99991 + (unit.sovereignId || 0) * 7919) *
			43758.5453;
		unit._discipline = Math.abs(seed - Math.floor(seed));
	}
	return unit._discipline;
}

function getUnitCommandPolicy(unit) {
	if (!warEconomyEnabled) {
		return {
			band: COMMAND_BANDS.PAID,
			refusesOffense: false,
			returnHome: false,
			selfDefenseOnly: false,
		};
	}
	let band = unit._commandBand;
	if (!band) {
		band =
			countryEconomy.get(unit.sovereignId)?.commandBand || COMMAND_BANDS.PAID;
		unit._commandBand = band;
	}
	let refusesOffense = unit._refusesOffense;
	if (typeof refusesOffense !== "boolean") {
		refusesOffense = getUnitDiscipline(unit) < commandRefusalShare(band);
		unit._refusesOffense = refusesOffense;
	}
	return {
		band,
		refusesOffense,
		returnHome:
			band === COMMAND_BANDS.BREAKDOWN || band === COMMAND_BANDS.MUTINY,
		selfDefenseOnly: band === COMMAND_BANDS.MUTINY,
	};
}

function clearUnitCommandAssignments(unit) {
	unit._assignedPlanSignature = null;
	unit._taskForceUid = null;
	unit._taskForceRole = null;
	unit._taskForceOrder = null;
	unit._transportPlanSignature = null;
	unit._planWaypointSignature = null;
	unit._planWaypointIndex = 0;
	unit.navalAssigned = false;
	unit.supplyAssigned = false;
	unit.coastalAssigned = false;
	unit.garrisonAssigned = false;
	unit._occupationGarrisonVictimId = null;
	unit._occupationGarrisonPointIndex = null;
	unit.frontSlot = null;
	unit._defenderReactTarget = null;
	unit._cachedTarget = null;
	unit._cachedLocalEnemyCount = 0;
	unit._cachedEnemyCentroidLat = 0;
	unit._cachedEnemyCentroidLng = 0;
}

function getUnitPersonnelFallback(unit) {
	const sideIdx = Number.isInteger(unit?.sideIndex) ? unit.sideIndex : -1;
	return sideIdx >= 0 && sideIdx < MAX_SIDES
		? soldiersPerUnit[sideIdx] || CONFIG.UNIT_TO_SOLDIER_RATIO
		: CONFIG.UNIT_TO_SOLDIER_RATIO;
}

function getLiveFormationPersonnel(unit) {
	return getFormationPersonnel(unit, {
		nominalPersonnel: getUnitPersonnelFallback(unit),
		baseHealth:
			unit?.maxHealth ||
			CONFIG.UNIT_HEALTH * (unit?.isAlpenjager ? CONFIG.ALPEN_HEALTH_MULT : 1),
	});
}

function getLiveFormationStrength(unit) {
	if (!unit || unit.kind === "armor") return 1;
	return getFormationStrengthMultiplier(unit, {
		referencePersonnel: CONFIG.UNIT_TO_SOLDIER_RATIO,
		nominalPersonnel: getUnitPersonnelFallback(unit),
		baseHealth:
			unit.maxHealth ||
			CONFIG.UNIT_HEALTH * (unit.isAlpenjager ? CONFIG.ALPEN_HEALTH_MULT : 1),
	});
}

function returnUnitPersonnelToReserve(unit) {
	const sideIdx = Number.isInteger(unit?.sideIndex) ? unit.sideIndex : -1;
	if (sideIdx < 0 || sideIdx >= MAX_SIDES) return 0;
	const personnel =
		unit.kind === "armor"
			? computeEquipmentPersonnel({ armoredVehicles: unit.equipment || 0 })
			: getLiveFormationPersonnel(unit);
	if (personnel > 0) {
		sideRecruitableManpower[sideIdx] += personnel;
	}
	return personnel;
}

function getFormationCapacityStrength(unit) {
	if (!unit || unit.kind === "armor") return 1;
	if (Number.isFinite(unit.personnelCapacity)) {
		return Math.max(0, unit.personnelCapacity / CONFIG.UNIT_TO_SOLDIER_RATIO);
	}
	return Math.max(0, getLiveFormationStrength(unit));
}

function setUnitFormationPersonnel(unit, personnel) {
	if (!unit || unit.kind === "armor") return unit;
	const wholePersonnel = Math.max(1, Math.round(Number(personnel) || 0));
	const strengthMultiplier =
		wholePersonnel / Math.max(1, CONFIG.UNIT_TO_SOLDIER_RATIO);
	const terrainHealthMultiplier = unit.isAlpenjager
		? CONFIG.ALPEN_HEALTH_MULT
		: 1;
	unit.personnel = wholePersonnel;
	unit.personnelCapacity = wholePersonnel;
	unit.nominalPersonnel = CONFIG.UNIT_TO_SOLDIER_RATIO;
	unit.strengthMultiplier = strengthMultiplier;
	unit.maxHealth =
		CONFIG.UNIT_HEALTH * strengthMultiplier * terrainHealthMultiplier;
	unit.health = unit.maxHealth;
	return unit;
}

function compactVariableStrengthFormationsForSide(
	sideIdx,
	targetPersonnel = null,
) {
	const formations = units.filter(
		(unit) => unit.sideIndex === sideIdx && unit.kind === "army",
	);
	if (formations.length === 0) return 0;
	const existingPersonnel = formations.reduce(
		(sum, unit) => sum + getLiveFormationPersonnel(unit),
		0,
	);
	const totalPersonnel = Math.max(
		formations.length,
		Math.round(targetPersonnel ?? existingPersonnel),
	);
	const budget = Math.min(
		formations.length,
		chooseFormationBudget(totalPersonnel),
	);
	if (budget >= formations.length) {
		const descriptors = distributeFormationPersonnel(
			totalPersonnel,
			formations.length,
			{ nominalPersonnel: CONFIG.UNIT_TO_SOLDIER_RATIO },
		);
		for (let index = 0; index < formations.length; index++) {
			setUnitFormationPersonnel(
				formations[index],
				descriptors[index].personnel,
			);
		}
		soldiersPerUnit[sideIdx] = CONFIG.UNIT_TO_SOLDIER_RATIO;
		return formations.length;
	}

	const countryGroups = new Map();
	for (const formation of formations) {
		let group = countryGroups.get(formation.sovereignId);
		if (!group) {
			group = [];
			countryGroups.set(formation.sovereignId, group);
		}
		group.push(formation);
	}
	const groups = [...countryGroups.entries()].sort(
		([leftId], [rightId]) => Number(leftId) - Number(rightId),
	);
	const minimumMarkers = Math.min(budget, groups.length);
	const markerRemainder = Math.max(0, budget - minimumMarkers);
	const markerQuotas = allocateLargestRemainderQuotas(
		groups.map(([countryId, group]) => ({
			countryId,
			weight: group.length,
		})),
		markerRemainder,
	);
	const markerQuotaByCountry = new Map(
		markerQuotas.map((entry) => [entry.countryId, entry.quota]),
	);
	for (let index = 0; index < minimumMarkers; index++) {
		const countryId = Number(groups[index][0]);
		markerQuotaByCountry.set(
			countryId,
			(markerQuotaByCountry.get(countryId) || 0) + 1,
		);
	}
	const personnelQuotas = allocateLargestRemainderQuotas(
		groups.map(([countryId, group]) => ({
			countryId,
			weight: group.length,
		})),
		totalPersonnel,
	);
	const personnelByCountry = new Map(
		personnelQuotas.map((entry) => [entry.countryId, entry.quota]),
	);
	const retained = new Set();
	for (const [rawCountryId, group] of groups) {
		const countryId = Number(rawCountryId);
		const quota = Math.min(
			group.length,
			markerQuotaByCountry.get(countryId) || 0,
		);
		if (quota <= 0) continue;
		const descriptors = distributeFormationPersonnel(
			personnelByCountry.get(countryId) || quota,
			quota,
			{ nominalPersonnel: CONFIG.UNIT_TO_SOLDIER_RATIO },
		);
		for (let markerIndex = 0; markerIndex < quota; markerIndex++) {
			const sourceIndex = Math.min(
				group.length - 1,
				Math.floor((markerIndex * group.length) / quota),
			);
			const survivor = group[sourceIndex];
			setUnitFormationPersonnel(survivor, descriptors[markerIndex].personnel);
			retained.add(survivor);
		}
	}
	units = units.filter(
		(unit) =>
			unit.sideIndex !== sideIdx || unit.kind !== "army" || retained.has(unit),
	);
	soldiersPerUnit[sideIdx] = CONFIG.UNIT_TO_SOLDIER_RATIO;
	return retained.size;
}

function applyPendingBenchmarkForceOverride() {
	const targetTotalPersonnel = _benchmarkForcePersonnelPerSide;
	if (!Number.isFinite(targetTotalPersonnel) || targetTotalPersonnel <= 0) {
		return;
	}
	for (let sideIdx = 0; sideIdx < sides.length; sideIdx++) {
		manualSideManpower[sideIdx] = targetTotalPersonnel;
		let equipmentPersonnel = 0;
		for (const unit of units) {
			if (
				unit.sideIndex !== sideIdx ||
				unit.kind !== "armor" ||
				unit.health <= 0
			) {
				continue;
			}
			equipmentPersonnel += computeEquipmentPersonnel({
				armoredVehicles: unit.equipment || 0,
			});
		}
		for (const wing of airWings) {
			if (
				wing.sideIndex !== sideIdx ||
				wing.equipment <= 0 ||
				wing.state === AIR_WING_STATES.EVACUATED
			) {
				continue;
			}
			equipmentPersonnel += computeEquipmentPersonnel({
				fighters: wing.role === "FIGHTER" ? wing.equipment : 0,
				strikeAircraft: wing.role === "STRIKE" ? wing.equipment : 0,
			});
		}
		compactVariableStrengthFormationsForSide(
			sideIdx,
			Math.max(1, Math.round(targetTotalPersonnel - equipmentPersonnel)),
		);
	}
	for (const unit of units) unit.deployTicks = 0;
	_benchmarkForcePersonnelPerSide = null;
}

function stableUnitCohort(unit, interval) {
	const numericId = Math.abs(Number(unit?.id) || 0);
	const stableId = Math.floor(numericId * 2_147_483_647) >>> 0;
	return interval > 0 ? stableId % interval : 0;
}

function resetSimulationOptimizationRuntime() {
	_simulationWorldGeneration++;
	_simulationJobs.clear("world-reset");
	_simulationPhaseWheel.setGeneration(_simulationWorldGeneration);
	soldiersPerUnit.fill(CONFIG.UNIT_TO_SOLDIER_RATIO);
	_territoryLedgerSnapshot = null;
	_territoryLedgerDecisionTick = Number.NEGATIVE_INFINITY;
	_territoryLedgerCitiesSource = null;
	_territoryLedgerCitiesLength = -1;
	_territoryLedgerAppliedCitiesRevision = -1;
	_coastalTopologyReady = false;
	_coastalLandIndices = [];
	_pendingProposalSides.length = 0;
	_pendingProposalSideSet.clear();
	_retiredSidePersonnelByUid.clear();
	_territoryLedger = createRuntimeTerritoryLedger();
	_frameSimulationCommitFlags.clear();
	_renderAdmissionDeferredFrames = 0;
}

function scheduleCoastalTopologyJob() {
	if (!landMask?.length || _simulationJobs.has("coastal-topology")) return;
	const generation = _simulationWorldGeneration;
	const coastal = [];
	_simulationJobs.enqueue(
		createDeterministicJob({
			id: "coastal-topology",
			generation,
			totalItems: landMask.length,
			maxItemsPerTurn: 80_000,
			processRange(start, end) {
				for (let index = start; index < end; index++) {
					if (landMask[index] === 0) continue;
					const column = index % gridWidth;
					const row = Math.floor(index / gridWidth);
					let coastalCell = false;
					for (
						let rowOffset = -1;
						rowOffset <= 1 && !coastalCell;
						rowOffset++
					) {
						for (let columnOffset = -1; columnOffset <= 1; columnOffset++) {
							if (rowOffset === 0 && columnOffset === 0) continue;
							const neighborRow = row + rowOffset;
							const neighborColumn = column + columnOffset;
							if (
								neighborRow < 0 ||
								neighborRow >= gridHeight ||
								neighborColumn < 0 ||
								neighborColumn >= gridWidth
							) {
								continue;
							}
							if (landMask[neighborRow * gridWidth + neighborColumn] === 0) {
								coastalCell = true;
								break;
							}
						}
					}
					if (coastalCell) coastal.push(index);
				}
			},
			onComplete() {
				if (generation !== _simulationWorldGeneration) return;
				_coastalLandIndices = coastal;
				_coastalTopologyReady = true;
				for (let sideIdx = 0; sideIdx < sides.length; sideIdx++) {
					if (sides[sideIdx]?.length) _planReassessNeeded[sideIdx] = true;
				}
			},
		}),
	);
}

function territoryLedgerMaps() {
	return {
		landMask,
		worldControlMap,
		dominantSideMap,
		deJureMap,
		primaryOccupierMap,
		occupationMap,
	};
}

function runtimeCountryToSideMap() {
	const mapping = new Map();
	for (let sideIndex = 0; sideIndex < sides.length; sideIndex++) {
		for (const country of sides[sideIndex] || []) {
			if (country?.id > 0) mapping.set(country.id, sideIndex);
		}
	}
	return mapping;
}

function publishTerritoryLedgerSnapshot(snapshot, decisionBoundary = false) {
	if (!snapshot) return false;
	_territoryLedgerSnapshot = snapshot;
	_cachedP1T = snapshot.positiveOccupationCells || 0;
	_cachedP2T = snapshot.negativeOccupationCells || 0;

	const counts = new Array(sides.length).fill(0);
	for (let sideIndex = 0; sideIndex < sides.length; sideIndex++) {
		counts[sideIndex] = getSideLedger(snapshot, sideIndex)?.territory || 0;
	}
	_cachedSideTerritoryCounts = counts;
	const total = counts.reduce((sum, count) => sum + count, 0);
	_cachedSideTerritoryPcts = counts.map((count) =>
		total > 0 ? Math.round((count / total) * 100) : 50,
	);

	if (decisionBoundary) {
		for (const country of sides.flat()) {
			if (!country) continue;
			const ledger = getCountryLedger(snapshot, country.id);
			country.lastOwnedCount = ledger?.owned || 0;
			country.lastControlledCount = ledger?.controlled || 0;
			country.lastFrontlineCount = ledger?.frontline || 0;
		}
		_territoryLedgerDecisionTick = _simTickCount;
	}
	return true;
}

function createRuntimeTerritoryLedger(
	countryToSide = runtimeCountryToSideMap(),
) {
	if (
		gridWidth <= 0 ||
		gridHeight <= 0 ||
		!landMask?.length ||
		landMask.length !== gridWidth * gridHeight
	) {
		return null;
	}
	const citySource = activeTheaterCities || [];
	_territoryLedgerCitiesSource = citySource;
	_territoryLedgerCitiesLength = citySource.length;
	_territoryLedgerAppliedCitiesRevision = _territoryLedgerCitiesRevision;
	return createTerritoryLedger({
		gridWidth,
		gridHeight,
		tileSize: 32,
		maps: territoryLedgerMaps(),
		countryToSide,
		sideUids,
		hostilityMatrix,
		maxSides: MAX_SIDES,
		topologyRevision: _simulationWorldGeneration,
		worldRevision: _simulationWorldGeneration,
		cityRevision: _territoryLedgerCitiesRevision,
		cities: citySource,
		getCityCellIndex: (city) => getGridIndex(city.lat, city.lng),
		countedLandValue: 2,
		defaultItemBudget: 160_000,
		onCommit: (snapshot) => publishTerritoryLedgerSnapshot(snapshot, false),
	});
}

function ensureRuntimeTerritoryLedger(countryToSide) {
	if (!_territoryLedger) {
		_territoryLedger = createRuntimeTerritoryLedger(countryToSide);
	}
	if (!_territoryLedger) return null;
	const topologyChanged = _territoryLedger.setSideTopology({
		countryToSide,
		sideUids,
		hostilityMatrix,
		maxSides: MAX_SIDES,
		revision: _simulationWorldGeneration,
	});
	if (topologyChanged) {
		_territoryLedgerSnapshot = null;
		_cachedSideTerritoryCounts = [];
		_cachedSideTerritoryPcts = [];
	}
	const citySource = activeTheaterCities || [];
	const citySourceChanged =
		_territoryLedgerCitiesSource !== citySource ||
		_territoryLedgerCitiesLength !== citySource.length;
	if (
		citySourceChanged ||
		_territoryLedgerAppliedCitiesRevision !== _territoryLedgerCitiesRevision
	) {
		if (
			citySourceChanged &&
			_territoryLedgerAppliedCitiesRevision === _territoryLedgerCitiesRevision
		) {
			_territoryLedgerCitiesRevision++;
		}
		_territoryLedger.setCities(citySource, {
			getCityCellIndex: (city) => getGridIndex(city.lat, city.lng),
			revision: _territoryLedgerCitiesRevision,
		});
		_territoryLedgerCitiesSource = citySource;
		_territoryLedgerCitiesLength = citySource.length;
		_territoryLedgerAppliedCitiesRevision = _territoryLedgerCitiesRevision;
		_territoryLedgerSnapshot = null;
	}
	return _territoryLedger;
}

function stepTerritoryLedger(countryToSide, itemBudget = 160_000) {
	const ledger = ensureRuntimeTerritoryLedger(countryToSide);
	if (!ledger) return null;
	const result = ledger.step(itemBudget);
	if (result.committed) _frameSimulationCommitFlags.add("territory-ledger");
	return result;
}

function flushTerritoryLedger(countryToSide = runtimeCountryToSideMap()) {
	const ledger = ensureRuntimeTerritoryLedger(countryToSide);
	if (!ledger) return null;
	const result = ledger.flush(160_000);
	if (result.committedGenerations > 0) {
		_frameSimulationCommitFlags.add("territory-ledger");
	}
	if (result.snapshot) publishTerritoryLedgerSnapshot(result.snapshot, false);
	return result.snapshot || _territoryLedgerSnapshot;
}

function registerSimulationPhaseJobs() {
	if (_simulationPhaseJobsRegistered) return;
	_simulationPhaseJobsRegistered = true;
	_simulationPhaseWheel.register({
		id: "operational-intel-decay",
		intervalTicks: 15,
		phaseOffset: 4,
		priority: 10,
		oncePerFrame: false,
		run: () => decayOperationalAiIntelContacts(),
	});
	_simulationPhaseWheel.register({
		id: "occupation-garrison-sync",
		intervalTicks: 60,
		phaseOffset: 17,
		priority: 20,
		oncePerFrame: false,
		run: () => syncOccupationGarrisonAssignments(),
	});
	_simulationPhaseWheel.register({
		id: "unit-consolidation",
		intervalTicks: 30,
		phaseOffset: 11,
		priority: 30,
		oncePerFrame: false,
		run: () => {
			const started = performance.now();
			const removed = consolidateOverlappingUnits();
			if (window.__perf) {
				window.__perf.consolidate =
					(window.__perf.consolidate || 0) + performance.now() - started;
			}
			return removed;
		},
	});
}

function advanceSimulationPhaseWheel() {
	registerSimulationPhaseJobs();
	const advanced = _simulationPhaseWheel.advance({
		tick: _simTickCount,
		frameToken: simFrameCount,
		context: { worldGeneration: _simulationWorldGeneration },
		itemBudget: 80_000,
	});
	const committed = _simulationPhaseWheel.flushReadyCommits({
		expectedGeneration: _simulationWorldGeneration,
		maxCommits: 2,
	});
	for (const ticket of committed.committed) {
		_frameSimulationCommitFlags.add(ticket.id);
	}
	if (advanced.errors.length || committed.errors.length) {
		console.error("[MW] Simulation phase job failed", {
			advance: advanced.errors,
			commit: committed.errors,
		});
	}
}

function consolidateOverlappingUnits() {
	if (units.length <= 40) return 0;
	const mergeDistSq = 0.14 * 0.14;
	const maxMergedHealth = CONFIG.UNIT_HEALTH * 5;
	const unitsToRemove = new Set();

	for (let index = 0; index < units.length; index++) {
		const unit = units[index];
		if (
			unitsToRemove.has(unit) ||
			unit.kind === "armor" ||
			unit.personnel !== undefined ||
			(unit.personnelCapacity || 0) > CONFIG.UNIT_TO_SOLDIER_RATIO ||
			unit.health >= maxMergedHealth ||
			unit.deployTicks > 0
		) {
			continue;
		}

		const hashX = Math.floor((unit.lng + 180) / UNIT_HASH_CELL_SIZE);
		const hashY = Math.floor((unit.lat + 90) / UNIT_HASH_CELL_SIZE);
		const hashKey = hashX * 100 + hashY;
		const sideIndex = unit.sideIndex;
		const cellUnits =
			CONFIG.ENABLE_SIDE_HASH_COMBAT &&
			sideIndex >= 0 &&
			sideIndex < sides.length
				? unitHashBySide[sideIndex].get(hashKey)
				: unitSpatialHash.get(hashKey);
		if (!cellUnits) continue;

		for (let otherIndex = 0; otherIndex < cellUnits.length; otherIndex++) {
			const other = cellUnits[otherIndex];
			if (
				other === unit ||
				unitsToRemove.has(other) ||
				other.kind === "armor" ||
				other.personnel !== undefined ||
				(other.personnelCapacity || 0) > CONFIG.UNIT_TO_SOLDIER_RATIO ||
				(CONFIG.ENABLE_SIDE_HASH_COMBAT
					? false
					: other.sideIndex === unit.sideIndex) ||
				other.sovereignId !== unit.sovereignId ||
				other.deployTicks > 0
			) {
				continue;
			}

			let deltaLng = other.lng - unit.lng;
			if (deltaLng > 180) deltaLng -= 360;
			else if (deltaLng < -180) deltaLng += 360;
			const distanceSq = (unit.lat - other.lat) ** 2 + deltaLng ** 2;
			if (distanceSq >= mergeDistSq) continue;

			const transfer = Math.min(maxMergedHealth - unit.health, other.health);
			unit.health += transfer;
			other.health -= transfer;
			if (other.health <= 0) unitsToRemove.add(other);
			if (unit.health >= maxMergedHealth) break;
		}
	}

	if (unitsToRemove.size > 0) {
		units = units.filter((unit) => !unitsToRemove.has(unit));
		_frameSimulationCommitFlags.add("unit-consolidation");
	}
	return unitsToRemove.size;
}

